List<int> parseNestedParens(String parenString) {
  final queue = Queue<String>();
  int depth = 0;
  List<int> result = [];

  for (int i = 0; i < parenString.length; i++) {
    String c = parenString[i];
    if (c == '(') {
      queue.add(c);
      depth++;
    } else if (c == ')') {
      if (queue.isNotEmpty && queue.last != '(') {
        // If the last element in the queue is not a '(', it's an invalid nesting.
        return null;
      }
      queue.removeLast();
      depth--;
      result.add(depth); // Add current depth after closing
    } else {
      // Invalid character, return null
      return null;
    }
  }

  // Check if all parentheses are properly closed and there's no leftover opening ones
  if (depth != 0 || !queue.isEmpty) {
    return null;
  }

  return result;
}
