List<double> rescaleToUnit(List<double> numbers) {
  if (numbers.isEmpty || numbers.length == 1) return List.filled(numbers.length, 0.0);

  double min = numbers.reduce(min);
  double max = numbers.reduce(max);

  if (min == max) {
    return List.filled(numbers.length, 0.0); // All values are the same
  }

  final scaledValues = <double>[];
